func headBankGemv(t *testing.T, spec string) {
	dev, done := newTestDevice(t)
	defer done()

	const nEmbd, vocab = 256, 640
	rng := rand.New(rand.NewSource(13))
	w := q8Tensor(rng, "output.weight", nEmbd, vocab)
	sim, err := ParseQuantSim(spec)
	if err != nil {
		t.Fatal(err)
	}
	sim.Mode = "rtn"
	bank, err := BankForSim(sim)
	if err != nil {
		t.Fatal(err)
	}

	g, err := NewHeadGPUBank(dev, nEmbd, w, 4, bank, sim)
	if err != nil {
		t.Fatal(err)
	}
	defer g.Destroy()

	x := make([]float32, nEmbd)
	for i := range x {
		x[i] = float32(rng.NormFloat64())
	}
	if err := g.Upload(x, 1); err != nil {
		t.Fatal(err)
	}
	if err := g.Run(); err != nil {
		t.Fatal(err)
	}
	gemm := append([]float32(nil), g.Logits()[:vocab]...)

	if err := g.SetGEMV(GEMVK1); err != nil {
		t.Fatal(err)
	}
	if err := g.Run(); err != nil {
		t.Fatal(err)
	}
	gemv := append([]float32(nil), g.Logits()[:vocab]...)

	var num, den float64
	for i := range gemm {
		d := float64(gemm[i] - gemv[i])
