python3 - <<'EOF'
p='shaders/llm_q4k.glsl'; s=open(p).read()
old='''// **The ten-group record**: LLM.md L8c-6, and the one place this bank is not
// ggml's.'''
new='''// The same pair without the branch (P21b): a lane's `j` differs across the
// wave in the split-K GEMVs, and a divergent `if` splits the basic block,
// which stops the scheduler hoisting the next step's loads above this
// step's arithmetic. Both arms are computed and one is selected.
void q4kScaleMinSel(uint j, uvec3 s, out uint sc, out uint mn) {
    uint lo = j < 4u ? j : j - 4u;
    uint hi = j < 4u ? j + 4u : j;
    uint bj = q4kByte(s, j), bj4 = q4kByte(s, j + 4u), bjm4 = q4kByte(s, lo);
    uint scA = bj & 63u, mnA = bj4 & 63u;
    uint a = bj4;
    uint scB = (a & 0xFu) | ((bjm4 >> 6) << 4);
    uint mnB = (a >> 4) | ((bj >> 6) << 4);
    sc = j < 4u ? scA : scB;
    mn = j < 4u ? mnA : mnB;
}

// **The ten-group record**: LLM.md L8c-6, and the one place this bank is not
// ggml's.'''
assert s.count(old)==1; s=s.replace(old,new)
old='''void q4kScaleMin12(uint j, uvec4 s, out uint sc, out uint mn) {
    uint b = j * 12u;
    uint w = b >> 5, o = b & 31u;
    uint v = s[w] >> o;
    if (o > 20u) {
        v |= s[w + 1u] << (32u - o);
    }
    sc = v & 63u;
    mn = (v >> 6) & 63u;
}'''
new='''void q4kScaleMin12(uint j, uvec4 s, out uint sc, out uint mn) {
    uint b = j * 12u;
    uint w = b >> 5, o = b & 31u;
    uint v = s[w] >> o;
    // Branch-free (P21b): the next word exists whenever the shift needs it
    // (j = 2 and 5), and the index is clamped for the ones where it does not.
    uint nx = s[min(w + 1u, 3u)] << ((32u - o) & 31u);
    v |= o > 20u ? nx : 0u;
    sc = v & 63u;
    mn = (v >> 6) & 63u;
}'''
assert s.count(old)==1; s=s.replace(old,new)
open(p,'w').write(s)
for p in ['shaders/llm_gemv.comp','shaders/llm_hc_gemv.comp']:
    s=open(p).read()
    # only inside the PERSLAB arm: it is the first q4kScaleMin( after '#ifdef PERSLAB'
    i=s.index('#ifdef PERSLAB'); j=s.index('#else', i)
    arm=s[i:j]
    assert arm.count('q4kScaleMin(')==1
    arm=arm.replace('q4kScaleMin(','q4kScaleMinSel(')
    s=s[:i]+arm+s[j:]
    open(p,'w').write(s)
print("ok")
EOF
