package llm

import (
	"math/rand"
	"testing"
)

// P21b's gate: a GEMV rung whose slab's loads are issued together
// (`-DPERSLAB`) is the same rung to the bit — the loads move, the record is
// decoded without a branch, and every product lands in the same accumulator
// in the same order. So each block below runs one row on its K-quant bank
// with GEMVHoist on and off and asks for identity, not tolerance; a hoisted
// build that is *not* identical has changed the arithmetic and is a
// different kernel.

func identical(t *testing.T, what string, a, b []float32) {
	t.Helper()
	if len(a) != len(b) {
		t.Fatalf("%s: %d values against %d", what, len(a), len(b))
	}
	if len(a) == 0 {
		t.Fatalf("%s: nothing to compare", what)
	}
	for i := range a {
		if a[i] != b[i] {
			t.Fatalf("%s[%d]: hoisted %.9g, the rung %.9g", what, i, a[i], b[i])
		}
	}
	t.Logf("%s: %d values identical", what, len(a))
}

func withHoist(t *testing.T, on bool, fn func()) {
	t.Helper()
	was := GEMVHoist
	GEMVHoist = on
	defer func() { GEMVHoist = was }()
	fn()
}

func TestDeltaNetGPUGemvHoistIsTheRung(t *testing.T) {
	tr, c, w, _ := dnFixtures(t, dnLayer)
	in, err := tr.Get(fmt.Sprintf("hc_mixed-%d", dnLayer), 0)
	if err != nil {
		t.Fatal(err)
	}
	sim, err := ParseQuantSim("q4_k/32")
	if err != nil {
		t.Fatal(err)
	}
	sim.Mode = "rtn"
	bank, err := BankForSim(sim)
	if err != nil {
		t.Fatal(err)
	}
	dev, done := newTestDevice(t)
	defer done()
	g, err := NewDeltaNetGPUBank(dev, c, 1, []DeltaNetWeights{w}, bank, sim)
	if err != nil {
		t.Fatal(err)
	}
	defer g.Destroy()
	run := func(on bool) (qkv, out []float32) {
		withHoist(t, on, func() {
			if err := g.Upload(in.Vals[:c.NEmbd], 1); err != nil {
				t.Fatal(err)
			}
			if err := g.SetGemv(dnQKVGemv, dnOutGemv); err != nil {
				t.Fatal(err)
			}
			if err := g.Run(0); err != nil {
				t.Fatal(err)
			}
			qkv = append([]float32(nil), g.Column(g.ColQ(), g.ColBeta()+c.NHeadV)...)
			out = append([]float32(nil), g.Result()...)
		})
		return
	}
	if gemvBankPipeRowsAt(dnQKVGemv, bank, 1, c.NEmbd) == gemvBankPipeRows(dnQKVGemv, bank, 1) {
		t.Fatalf("no hoisted build for %s at K = %d", dnQKVGemv, c.NEmbd)
	}
	hq, ho := run(true)
	rq, ro := run(false)
	identical(t, "dn.qkv", hq, rq)
	identical(t, "dn.out", ho, ro)
}

func TestAttnGPUGemvHoistIsTheRung(t *testing.T) {
	_, tr, c, w, _, nKV := attnFixtures(t)
	in, err := tr.Get("hc_mixed-3", 0)
	if err != nil {
		t.Fatal(err)
	}
