func TestHeadGPUGemvHoistIsTheRung(t *testing.T) {
	dev, done := newTestDevice(t)
	defer done()
	// The head's build is for the model's K; the vocabulary is a few blocks.
	const nEmbd, vocab = 2560, 640
	rng := rand.New(rand.NewSource(31))
	w := q8Tensor(rng, "output.weight", nEmbd, vocab)
	sim, err := ParseQuantSim("q5_k/32")
	if err != nil {
		t.Fatal(err)
	}
	sim.Mode = "rtn"
	bank, err := BankForSim(sim)
	if err != nil {
		t.Fatal(err)
	}
	g, err := NewHeadGPUBank(dev, nEmbd, w, 1, bank, sim)
	if err != nil {
		t.Fatal(err)
	}
	defer g.Destroy()
	x := make([]float32, nEmbd)
	for i := range x {
		x[i] = float32(rng.NormFloat64())
	}
	run := func(on bool) (l []float32) {
		withHoist(t, on, func() {
			if err := g.Upload(x, 1); err != nil {
				t.Fatal(err)
			}
			if err := g.Run(); err != nil {
				t.Fatal(err)
			}
			l = append([]float32(nil), g.Logits()[:vocab]...)
		})
		return
	}
	if g.gemv == GEMVOff {
		t.Fatal("one row on a quantised bank did not plan the GEMV")
	}
	if gemvBankPipeRowsAt(GEMVK1, bank, 1, nEmbd) == gemvBankPipeRows(GEMVK1, bank, 1) {
		t.Fatalf("no hoisted build for the head at K = %d", nEmbd)
	}
	identical(t, "head", run(true), run(false))
}

func TestHCGPUGemvHoistIsTheRung(t *testing.T) {
	dev, done := newTestDevice(t)
	defer done()
	cfg := HCConfig{NEmbd: 2560, HC: 4, LowRank: 320, Eps: 1e-6}
	wide := cfg.Wide()
	rng := rand.New(rand.NewSource(37))
	sim, err := ParseQuantSim("q5_k/32")
	if err != nil {
		t.Fatal(err)
	}
	sim.Mode = "rtn"
	bank, err := BankForSim(sim)
	if err != nil {
		t.Fatal(err)
	}
	w := HCWeights{
		Norm:   make([]float32, wide),
		Down:   make([]float32, cfg.LowRank*wide),
		Up:     make([]float32, wide*cfg.LowRank),
		Inject: make([]float32, cfg.HC*wide),
		Name:   "blk.0.hc_attn_",
	}
	for i := range w.Norm {
		w.Norm[i] = 1 + float32(rng.NormFloat64())*0.1
	}
	for _, x := range [][]float32{w.Down, w.Up, w.Inject} {
