				t.Fatal(err)
			}
			if err := g.Run(0, false); err != nil {
				t.Fatal(err)
			}
			return append([]float32(nil), g.Lo()...)
		}
		identical(t, fmt.Sprintf("%d rows hc.down (lo)", rows), run(HCDownGemv32P), run(HCDownGemv32))
	}
}
